pub fn wrap(text: Str, width: Int) -> List[Str] {
  var pieces: List[Str] = []
  for raw in text.split(" ") {
    if raw.len() > width {
      var start = 0
      while start < raw.len() {
        var stop = start + width
        if stop > raw.len() {
          stop = raw.len()
        }
        pieces = pieces.push(raw.slice(start, stop))
        start = stop
      }
    } else {
      if raw.len() > 0 {
        pieces = pieces.push(raw)
      }
    }
  }
  var lines: List[Str] = []
  var line = ""
  for w in pieces {
    if line.len() == 0 {
      line = w
    } else {
      if line.len() + 1 + w.len() <= width {
        line = line + " " + w
      } else {
        lines = lines.push(line)
        line = w
      }
    }
  }
  if line.len() > 0 {
    lines = lines.push(line)
  }
  return lines
}
